def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    f = str(frequency).lower()
    p = 24 if 'hour' in f else (7 if 'day' in f else 1)
    if len(y) < p:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h

    candidates = [(width, alpha) for width in (2, 3, 4, 5) for alpha in (0.0, 0.25, 0.5, 0.75, 1.0)]
    candidates.append((1, 1.0))

    def make(train, count, width, alpha):
        cycles = max(1, len(train) // p)
        width = min(width, cycles)
        output = []
        for k in range(count):
            phase = k % p
            values = [train[len(train) - j * p + phase] for j in range(1, width + 1)]
            latest = values[0]
            robust = statistics.median(values)
            prediction = alpha * latest + (1.0 - alpha) * robust
            output.append(float(prediction))
        return output

    def smape(actual, predicted):
        terms = []
        for a, b in zip(actual, predicted):
            denominator = abs(a) + abs(b)
            if denominator > 1e-12:
                terms.append(200.0 * abs(a - b) / denominator)
        return sum(terms) / len(terms) if terms else 0.0

    fold_count = min(5, len(y) // p - 2)
    folds = []
    for back in range(fold_count, 0, -1):
        cut = len(y) - back * p
        if cut >= 2 * p:
            folds.append((y[:cut], y[cut:cut + p]))

    if not folds:
        return make(y, h, 1, 1.0)

    scored = []
    for width, alpha in candidates:
        errors = [smape(actual, make(train, len(actual), width, alpha)) for train, actual in folds]
        weights = [2.0 ** i for i in range(len(errors))]
        weighted = sum(w * e for w, e in zip(weights, errors)) / sum(weights)
        instability = statistics.median([abs(errors[i] - errors[i - 1]) for i in range(1, len(errors))]) if len(errors) > 1 else 0.0
        scored.append((weighted + 0.10 * instability, weighted, width, alpha))
    scored.sort()
    _, _, width, alpha = scored[0]
    return make(y, h, width, alpha)
